with filtered as (select id, customer_id, device, browser, started_at, country, to_date(started_at) as started_at_date, trim(device) as clean_device, coalesce(country, 'DIRECT') as resolved_country from sessions where country is not null), with_gaps as (select *, case when started_at - lag(started_at) over (partition by customer_id order by started_at, id) > interval '7' day then 1 else 0 end as is_new_session from filtered), sessions_sessions as (select id, customer_id, browser, started_at, country, clean_device, resolved_country, sum(is_new_session) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as session_id from with_gaps) select date_trunc('year', started_at) as year_start, case when session_id >= 6 then 'PREMIUM' else 'STANDARD' end as session_id_tier, count_if(country = 'DE') as de_events, sort_array(collect_set(country)) as country_list, max(started_at) as ended_at, min(started_at) as first_seen, sum(session_id) as total_session_id, count(*) as row_count, grouping_id() as grouping_level from sessions_sessions group by grouping sets ((date_trunc('year', started_at), case when session_id >= 6 then 'PREMIUM' else 'STANDARD' end), (date_trunc('year', started_at)), ());
